def score_(b):
    g = b.grid
    s = 0
    if g[2][3] == 1:
        s += 2
    if g[1][3] == 2:
        s += 1
    s += min(2, sum(1 for c in (0, 1, 2) if g[0][c] == 2))
    s -= sum(1 for c in (0, 1) for r in (0, 1) if g[r][c] == 1)
    if g[0][4] == 2:
        s -= 2
    s -= b.heights[4]
    if b.ply <= 10:
        s += 1
    if b.ply >= 22:
        s -= 1
    return s

def fires(b):
    return score_(b) >= 4

def level(b):
    return max(0, min(9, 2 * score_(b) - 1))

def score_(b):
    g = b.grid
    s = 0.0
    # center column built up with my stone in the third cell
    if g[2][3] == 1:
        s += 2
    if g[1][3] != 0:
        s += 1
    # right-of-center column empty
    s -= 0.7 * b.heights[4]
    if g[0][4] == 2:
        s -= 1
    # their stones low on the left, mine absent there
    s += 0.5 * sum(1 for c in (0, 1, 2) if g[0][c] == 2)
    s -= 0.5 * sum(1 for c in (0, 1, 2) for r in (0, 1, 2) if g[r][c] == 1)
    # fewer stones overall
    s -= 0.08 * b.ply
    return s

def fires(b):
    s = score_(b)
    return max(0.0, min(1.0, (s + 1.0) / 4.0))

def level(b):
    return max(0, min(9, int(round(2 * score_(b) + 2))))

def score_(b):
    g = b.grid
    h = b.heights
    s = 0.0
    if 2 <= h[3] <= 5:
        s += 1.5
    if g[2][3] == 1:
        s += 1.5
    if g[1][3] == 1:
        s += 0.5
    if g[0][3] == 2:
        s += 0.5
    s -= 0.25 * sum(h[c] for c in range(7) if c != 3)
    s -= 0.5 * h[4]
    return s

def fires(b):
